def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    last_my = my[-1]
    last_op = op[-1]

    my_d_total = 0
    opp_d_total = 0
    for a in my:
        if a == 'D':
            my_d_total += 1
    for a in op:
        if a == 'D':
            opp_d_total += 1

    recent10 = op[-10:] if n >= 10 else op
    recent_op_d = 0
    for a in recent10:
        if a == 'D':
            recent_op_d += 1

    op_streak_D = 0
    i = n - 1
    while i >= 0 and op[i] == 'D':
        op_streak_D += 1
        i -= 1

    mutual_c_streak = 0
    i = n - 1
    while i >= 0 and my[i] == 'C' and op[i] == 'C':
        mutual_c_streak += 1
        i -= 1

    likely_punish = False
    if last_op == 'D':
        start = n - op_streak_D
        pre_dc = False
        j = max(0, start - 5)
        while j < start:
            if my[j] == 'D' and op[j] == 'C':
                pre_dc = True
            j += 1
        if pre_dc and opp_d_total <= max(3, n // 4) and recent_op_d <= 4:
            likely_punish = True

    simul_mutual_D = False
    if last_my == 'D' and last_op == 'D' and op_streak_D >= 2:
        if opp_d_total <= max(3, n // 4):
            start = n - op_streak_D
            if start >= 0 and my[start] == 'D' and op[start] == 'D':
                simul_mutual_D = True

    rewarded = 0
    punished = 0
    for i in range(n - 1):
        if my[i] == 'D' and op[i] == 'C':
            if op[i + 1] == 'C':
                rewarded += 1
            elif op[i + 1] == 'D':
                punished += 1

    net_reward = rewarded - punished

    exploitable = False
    if punished == 0 and rewarded >= 1 and opp_d_total == 0:
        exploitable = True
    elif punished == 0 and rewarded >= 2 and opp_d_total <= max(2, n // 5):
        exploitable = True
    elif net_reward >= 3 and rewarded >= punished + 2 and opp_d_total <= max(3, n // 3):
        exploitable = True

    weak_exploit = (
        not exploitable
        and net_reward >= 1
        and opp_d_total <= max(2, n // 4)
        and recent_op_d <= 2
    )

    if n == 98:
        if exploitable:
            return 'D'
        if last_op == 'C':
            if weak_exploit and rng.random() < 0.25:
                return 'D'
            return 'C'

        if likely_punish or simul_mutual_D:
            return 'C' if rng.random() < 0.6 else 'D'
        if opp_d_total > (n * 8) // 10:
            return 'D'
        if opp_d_total <= max(3, n // 4):
            return 'C' if rng.random() < 0.3 else 'D'
        return 'D'

    if last_op == 'D':
        if opp_d_total > (n * 8) // 10:
            return 'D'

        if simul_mutual_D and op_streak_D <= 3:
            return 'C' if rng.random() < 0.7 else 'D'

        if likely_punish:
            if op_streak_D == 1:
                return 'C'
            if op_streak_D == 2:
                if last_my == 'C':
                    return 'C'
                return 'C' if rng.random() < 0.65 else 'D'
            return 'C' if rng.random() < 0.45 else 'D'

        if op_streak_D == 1:
            return 'D'

        if last_my == 'D':
            if (
                opp_d_total <= max(3, n // 4)
                and op_streak_D >= 4
                and rng.random() < 0.35
            ):
                return 'C'
            return 'D'

        if (
            opp_d_total <= max(3, n // 4)
            and op_streak_D >= 5
            and rng.random() < 0.3
        ):
            return 'C'
        return 'D'

    if exploitable:
        return 'D'

    if last_my == 'D':
        if weak_exploit and rng.random() < 0.35:
            return 'D'
        return 'C'

    if opp_d_total == 0 and my_d_total == 0 and mutual_c_streak >= 14:
        return 'D'

    test_prob = 0.0

    if punished == 0 and opp_d_total == 0 and my_d_total > 0:
        if mutual_c_streak >= 4 or rewarded >= 1:
            test_prob = 0.12
    elif punished == 0 and recent_op_d == 0 and opp_d_total <= max(2, n // 6):
        if mutual_c_streak >= 25:
            test_prob = 0.04
    elif net_reward >= 1 and punished <= rewarded and recent_op_d <= 1:
        if mutual_c_streak >= 30:
            test_prob = 0.03
    elif opp_d_total <= max(2, n // 6) and mutual_c_streak >= 45:
        test_prob = 0.02

    if test_prob > 0.0 and rng.random() < test_prob:
        return 'D'

    return 'C'
